function contextualObjectiveText(language: 'es' | 'fr', title: string, id: string): string {
  const override = scenarioObjectiveOverrides[language][title]?.[id];
  if (override) return override;
  if (language === 'es') {
    const action = esObjectiveText[id];
    if (!action) throw new Error(`Missing Spanish objective copy for ${title}/${id}`);
    return action;
  }
  const action = frObjectiveText[id];
  if (!action) throw new Error(`Missing French objective copy for ${title}/${id}`);
  return action;
}
const esScenario = (
  title: string, goal: string, role: string, setting: string, persona: string, hint: string, greeting: string,
  objectiveIds: readonly string[], safeFallback: string | null = null,
): DialogueTargetScenario => ({ title, goal, role, setting, persona, hint, greeting, safeFallback,
  objectives: objectiveIds.map((id) => ({ id, text: contextualObjectiveText('es', title, id) })),
});

