// Le français a son propre décor et sa propre voix. Les identifiants restent
// stables afin que le runtime puisse comparer les objectifs sans traduire un
// scénario anglais au moment de l'exécution.
const frScenario = (
  title: string, goal: string, role: string, setting: string, persona: string, hint: string, greeting: string,
  objectiveIds: readonly string[], safeFallback: string | null = null,
): DialogueTargetScenario => ({ title, goal, role, setting, persona, hint, greeting, safeFallback,
  objectives: objectiveIds.map((id) => ({ id, text: contextualObjectiveText('fr', title, id) })),
});

