const deScenario = (title: string, goal: string, role: string, setting: string, persona: string, hint: string, greeting: string, objectiveIds: readonly string[], safeFallback: string | null = null): DialogueTargetScenario => ({
  title, goal, role, setting, persona, hint, greeting, safeFallback,
  objectives: objectiveIds.map((id) => {
    const text = deScenarioObjectiveOverrides[title]?.[id] ?? deObjectiveText[id];
    if (!text) throw new Error(`Missing German objective copy for ${title}/${id}`);
    return { id, text };
  }),
});

