export function dialogueScenarioForTarget(
  scenario: DialogScenario,
  target: DialogueStudyTarget,
): (DialogScenario & { targetScenario?: DialogueTargetScenario }) | null {
  if (target === 'en') return scenario;
  const pack = DIALOGUE_LANGUAGE_PACKS[target];
  const targetScenario = pack?.scenarios[scenario.id];
  return targetScenario ? { ...scenario, targetScenario } : null;
}

export function targetScenarioTemperament(
  scenario: DialogScenario,
): DialogTemperament | undefined {
  return scenario.temperament;
}


